<?php declare(strict_types=1);namespace NpmGateway\Tests\Unit;use NpmGateway\Services\MarketingFlyerImageProcessor;use PHPUnit\Framework\Attributes\DataProvider;use PHPUnit\Framework\TestCase;final class MarketingFlyerImageRejectionTest extends TestCase{public static function invalidFiles():array{return[['corrupt.png','not an image'],['document.pdf',"%PDF-1.7\n"],['vector.svg','<svg xmlns="http://www.w3.org/2000/svg"></svg>'],['disguised.jpg','plain text']];}#[DataProvider('invalidFiles')]public function testNonImagesAreRejectedByServerInspection(string$name,string$bytes):void{$path=tempnam(sys_get_temp_dir(),'mfcert-invalid-');file_put_contents($path,$bytes);try{$this->expectException(\InvalidArgumentException::class);(new MarketingFlyerImageProcessor())->validate(['name'=>$name,'tmp_name'=>$path,'size'=>filesize($path),'error'=>UPLOAD_ERR_OK]);}finally{@unlink($path);}}public function testBrowserNameDoesNotControlDetectedType():void{$path=tempnam(sys_get_temp_dir(),'mfcert-valid-');$im=imagecreatetruecolor(100,200);imagepng($im,$path);imagedestroy($im);try{$valid=(new MarketingFlyerImageProcessor())->validate(['name'=>'traversal/evil.jpg','tmp_name'=>$path,'size'=>filesize($path),'error'=>UPLOAD_ERR_OK]);self::assertSame('image/png',$valid['mime_type']);self::assertSame('png',$valid['extension']);}finally{@unlink($path);}}public function testDeclaredOversizeIsRejectedBeforeDecode():void{$path=tempnam(sys_get_temp_dir(),'mfcert-size-');file_put_contents($path,'x');try{$this->expectException(\InvalidArgumentException::class);(new MarketingFlyerImageProcessor())->validate(['name'=>'huge.png','tmp_name'=>$path,'size'=>MarketingFlyerImageProcessor::MAX_BYTES+1,'error'=>UPLOAD_ERR_OK]);}finally{@unlink($path);}}}
